export type CommentSnippet = {
    authorChannelId?: CommentSnippetAuthorChannelId;
    /**
     * Link to the author's YouTube channel, if any.
     */
    authorChannelUrl?: string;
    /**
     * The name of the user who posted the comment.
     */
    authorDisplayName?: string;
    /**
     * The URL for the avatar of the user who posted the comment.
     */
    authorProfileImageUrl?: string;
    /**
     * Whether the current viewer can rate this comment.
     */
    canRate?: boolean;
    /**
     * The id of the corresponding YouTube channel. In case of a channel comment this is the channel the comment refers to. In case of a video comment it's the video's channel.
     */
    channelId?: string;
    /**
     * The total number of likes this comment has received.
     */
    likeCount?: number;
    /**
     * The comment's moderation status. Will not be set if the comments were requested through the id filter.
     */
    moderationStatus?: 'published' | 'heldForReview' | 'likelySpam' | 'rejected';
    /**
     * The unique id of the parent comment, only set for replies.
     */
    parentId?: string;
    /**
     * The date and time when the comment was originally published.
     */
    publishedAt?: string;
    /**
     * The comment's text. The format is either plain text or HTML dependent on what has been requested. Even the plain text representation may differ from the text originally posted in that it may replace video links with video titles etc.
     */
    textDisplay?: string;
    /**
     * The comment's original raw text as initially posted or last updated. The original text will only be returned if it is accessible to the viewer, which is only guaranteed if the viewer is the comment's author.
     */
    textOriginal?: string;
    /**
     * The date and time when the comment was last updated.
     */
    updatedAt?: string;
    /**
     * The ID of the video the comment refers to, if any.
     */
    videoId?: string;
    /**
     * The rating the viewer has given to this comment. For the time being this will never return RATE_TYPE_DISLIKE and instead return RATE_TYPE_NONE. This may change in the future.
     */
    viewerRating?: 'none' | 'like' | 'dislike';
};

/**
 * The id of the author's YouTube channel, if any.
 */
export type CommentSnippetAuthorChannelId = {
    value?: string;
};

/**
 * A *comment thread* represents information that applies to a top level comment and all its replies. It can also include the top level comment itself and some of the replies.
 */
export type CommentThread = {
    /**
     * Etag of this resource.
     */
    etag?: string;
    /**
     * The ID that YouTube uses to uniquely identify the comment thread.
     */
    id?: string;
    /**
     * Identifies what kind of resource this is. Value: the fixed string "youtube#commentThread".
     */
    kind?: string;
    replies?: CommentThreadReplies;
    snippet?: CommentThreadSnippet;
};

export type CommentThreadListResponse = {
    /**
     * Etag of this resource.
     */
    etag?: string;
    /**
     * Serialized EventId of the request which produced this response.
     */
    eventId?: string;
    /**
     * A list of comment threads that match the request criteria.
     */
    items?: Array<CommentThread>;
    /**
     * Identifies what kind of resource this is. Value: the fixed string "youtube#commentThreadListResponse".
     */
    kind?: string;
    /**
     * The token that can be used as the value of the pageToken parameter to retrieve the next page in the result set.
     */
    nextPageToken?: string;
    pageInfo?: PageInfo;
    tokenPagination?: TokenPagination;
    /**
     * The visitorId identifies the visitor.
     */
    visitorId?: string;
};

/**
 * Comments written in (direct or indirect) reply to the top level comment.
 */
export type CommentThreadReplies = {
    /**
     * A limited number of replies. Unless the number of replies returned equals total_reply_count in the snippet the returned replies are only a subset of the total number of replies.
     */
    comments?: Array<Comment>;
};

/**
 * Basic details about a comment thread.
 */
export type CommentThreadSnippet = {
    /**
     * Whether the current viewer of the thread can reply to it. This is viewer specific - other viewers may see a different value for this field.
     */
    canReply?: boolean;
    /**
     * The YouTube channel the comments in the thread refer to or the channel with the video the comments refer to. If video_id isn't set the comments refer to the channel itself.
     */
    channelId?: string;
    /**
     * Whether the thread (and therefore all its comments) is visible to all YouTube users.
     */
    isPublic?: boolean;
    topLevelComment?: Comment;
    /**
     * The total number of replies (not including the top level comment).
     */
    totalReplyCount?: number;
    /**
     * The ID of the video the comments refer to, if any. No video_id implies a channel discussion comment.
     */
    videoId?: string;
};

